// Generates the C# vocabulary constants (src/LinkedArtNet/Vocabulary/*.g.cs) from the JSON registries in
// vocabulary/. Run after editing a registry:  dotnet run --project tools/VocabGen
// VocabularyTests checks the generated files are in sync with the JSON.

using System.Text;
using System.Text.Json;

var repoRoot = args.Length > 0 ? args[0] : FindRepoRoot();
var vocabDir = Path.Combine(repoRoot, "vocabulary");
var outDir = Path.Combine(repoRoot, "src", "LinkedArtNet", "Vocabulary");

var registries = new (string File, string Class, string Summary)[]
{
    ("aat.json", "Aat", "Getty Art &amp; Architecture Thesaurus terms used across Linked Art."),
    ("tgn.json", "Tgn", "Getty Thesaurus of Geographic Names places used in the examples."),
    ("ulan.json", "Ulan", "Getty Union List of Artist Names actors used in the examples."),
};

foreach (var (file, className, summary) in registries)
{
    var path = Path.Combine(vocabDir, file);
    var registry = JsonSerializer.Deserialize<Registry>(File.ReadAllText(path), JsonOptions.Default)!;
    Validate(registry, file);
    var code = Generate(registry, className, summary, file);
    var outPath = Path.Combine(outDir, className + ".g.cs");
    File.WriteAllText(outPath, code, new UTF8Encoding(false));
    Console.WriteLine($"{file}: {registry.Terms.Count} terms -> {Path.GetRelativePath(repoRoot, outPath)}");
}

static void Validate(Registry registry, string file)
{
    var names = new HashSet<string>(StringComparer.Ordinal);
    var canonicalIds = new HashSet<string>(StringComparer.Ordinal);
    var allNames = registry.Terms.Select(t => t.Name).ToHashSet(StringComparer.Ordinal);
    foreach (var term in registry.Terms)
    {
        if (!names.Add(term.Name)) throw new InvalidDataException($"{file}: duplicate name '{term.Name}'.");
        if (term.AliasOf is null && !canonicalIds.Add(term.Id))
            throw new InvalidDataException($"{file}: id {term.Id} appears twice without aliasOf (names '{term.Name}' and an earlier term).");
        if (term.AliasOf is not null && !allNames.Contains(term.AliasOf))
            throw new InvalidDataException($"{file}: '{term.Name}' is aliasOf unknown term '{term.AliasOf}'.");
        if (term.AliasOf is not null && registry.Terms.First(t => t.Name == term.AliasOf).Id != term.Id)
            throw new InvalidDataException($"{file}: '{term.Name}' is aliasOf '{term.AliasOf}' but their ids differ.");
    }
}

static string Generate(Registry registry, string className, string summary, string file)
{
    var sb = new StringBuilder();
    sb.AppendLine("// <auto-generated>");
    sb.AppendLine($"//     Generated by tools/VocabGen from vocabulary/{file}. Do not edit; edit the JSON and rerun the tool.");
    sb.AppendLine("// </auto-generated>");
    sb.AppendLine();
    sb.AppendLine("namespace LinkedArtNet.Vocabulary;");
    sb.AppendLine();
    sb.AppendLine($"/// <summary>{summary}</summary>");
    sb.AppendLine($"public static partial class {className}");
    sb.AppendLine("{");

    foreach (var term in registry.Terms)
    {
        var doc = term.Notes ?? term.Label;
        if (term.AliasOf is not null) doc += $" (same id as {term.AliasOf}, with this label)";
        sb.AppendLine($"    /// <summary>{Escape(doc)} ({term.Id})</summary>");
        var (returnType, factory) = term.Kind switch
        {
            "Material" => ("Material", "MakeMaterial"),
            "Language" => ("Language", "MakeLanguage"),
            "Currency" => ("Currency", "MakeCurrency"),
            "MeasurementUnit" => ("MeasurementUnit", "MakeUnit"),
            "Place" => ("Place", "MakePlace"),
            "Person" => ("Person", "MakePerson"),
            "Group" => ("Group", "MakeGroup"),
            _ => ("Type", "MakeType"),
        };
        var extra = term.Kind == "Language" ? $", {Literal(term.Notation)}" : "";
        sb.AppendLine($"    public static {returnType} {term.Name} => {factory}(\"{term.Id}\", {Literal(term.Label)}{extra});");
        sb.AppendLine();
    }

    sb.AppendLine("    /// <summary>Every term in the registry, in file order.</summary>");
    sb.AppendLine("    public static IReadOnlyList<VocabularyTerm> Terms { get; } =");
    sb.AppendLine("    [");
    foreach (var term in registry.Terms)
    {
        sb.AppendLine($"        new(\"{term.Name}\", \"{term.Id}\", {Literal(term.Label)}, VocabularyKind.{term.Kind ?? "Type"}, {Literal(term.Notation)}, {Literal(term.AliasOf)}),");
    }
    sb.AppendLine("    ];");
    sb.AppendLine("}");
    return sb.ToString();
}

static string Literal(string? s) => s is null ? "null" : "\"" + s.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"";

static string Escape(string s) => s.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;");

static string FindRepoRoot()
{
    var dir = new DirectoryInfo(AppContext.BaseDirectory);
    while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "linked-art-net.slnx"))) dir = dir.Parent;
    return dir?.FullName ?? throw new InvalidOperationException("Run from within the repository, or pass its root as the first argument.");
}

sealed record Registry(string Source, List<Term> Terms);

sealed record Term(string Name, string Id, string Label, string? Kind, string? Notation, string? AliasOf, string? Notes);

static class JsonOptions
{
    public static readonly JsonSerializerOptions Default = new() { PropertyNameCaseInsensitive = true, ReadCommentHandling = JsonCommentHandling.Skip, AllowTrailingCommas = true };
}
